    Bug 1871733 - Adjust add-on startup time and wait for about:3pane being fully loaded in messageDisplay.getDisplayedMessage(). r=mkmelin

    This patch adjusts the add-on startup time to recent changes of the
    startup sequence. The API method messageDisplay.getDisplayedMessage()
    also waits until about:3pane is fully loaded before trying to return
    the currently displayed message.

    Differential Revision: https://phabricator.services.mozilla.com/D235774

diff --git a/mail/base/content/about3Pane.js b/mail/base/content/about3Pane.js
index c8684eb952a..ecd5d5a3f22 100644
--- a/mail/base/content/about3Pane.js
+++ b/mail/base/content/about3Pane.js
@@ -104,6 +104,11 @@ var paneLayout;
  */
 var messagePane;

+/**
+ * A Promise with resolvers, indicating if DOMContentLoaded has finished.
+ */
+var hasDOMContentLoaded = Promise.withResolvers();
+
 /**
  * This is called at midnight to have messages grouped by their relative date
  * (such as today, yesterday, etc.) correctly categorized.
@@ -198,6 +203,9 @@ window.addEventListener("DOMContentLoaded", async event => {
   CalMetronome.on("day", refreshGroupedBySortView);

   updateZoomCommands();
+
+  // Update the state of the about:3pane being fully loaded.
+  hasDOMContentLoaded.resolve();
 });

 window.addEventListener("unload", () => {
diff --git a/mail/base/content/messenger.js b/mail/base/content/messenger.js
index 56392d29349..5701a136924 100644
--- a/mail/base/content/messenger.js
+++ b/mail/base/content/messenger.js
@@ -272,15 +272,15 @@ var gMailInit = {
     PeriodicFilterManager.setupFiltering();
     msgDBCacheManager.init();

-    this.delayedStartupFinished = true;
-    _resolveDelayedStartup(window);
-    Services.obs.notifyObservers(window, "browser-delayed-startup-finished");
-
-    // Notify observer to resolve the browserStartupPromise, which is used for the
-    // delayed background startup of WebExtensions.
-    Services.obs.notifyObservers(window, "extensions-late-startup");
-
-    this._loadComponentsAtStartup();
+    this._loadComponentsAtStartup().then(() => {
+      this.delayedStartupFinished = true;
+      _resolveDelayedStartup(window);
+      Services.obs.notifyObservers(window, "browser-delayed-startup-finished");
+
+      // Notify observer to resolve the browserStartupPromise, which is used for the
+      // delayed background startup of WebExtensions.
+      Services.obs.notifyObservers(window, "extensions-late-startup");
+    });
   },

   /**
diff --git a/mail/components/extensions/parent/ext-messageDisplay.js b/mail/components/extensions/parent/ext-messageDisplay.js
index b53690ac9ca..2880a5c8827 100644
--- a/mail/components/extensions/parent/ext-messageDisplay.js
+++ b/mail/components/extensions/parent/ext-messageDisplay.js
@@ -175,26 +175,30 @@ this.messageDisplay = class extends ExtensionAPIPersistent {
         ? tabManager.get(tabId)
         : tabManager.wrapTab(tabTracker.activeTab);
       if (tab?.type == "mail") {
+        const contentWindow = tab.nativeTab.chromeBrowser.contentWindow;
+        if (!contentWindow) {
+          return null;
+        }
+        await contentWindow.hasDOMContentLoaded.promise;
+
         // In about:3pane only the messageBrowser needs to be checked for its
         // load state. The webBrowser is invalid, the multiMessageBrowser can
         // bypass.
-        if (!tab.nativeTab.chromeBrowser.contentWindow.webBrowser.hidden) {
+        if (!contentWindow.webBrowser.hidden) {
           return null;
         }
-        if (
-          tab.nativeTab.chromeBrowser.contentWindow.messagePane.isMultiMessageBrowserVisible()
-        ) {
+        if (contentWindow.messagePane.isMultiMessageBrowserVisible()) {
           return tab;
         }
-        msgContentWindow =
-          tab.nativeTab.chromeBrowser.contentWindow.messageBrowser
-            .contentWindow;
+        msgContentWindow = contentWindow.messageBrowser.contentWindow;
       } else if (tab?.type == "messageDisplay") {
         msgContentWindow =
           tab instanceof TabmailTab
             ? tab.nativeTab.chromeBrowser.contentWindow
             : tab.nativeTab.messageBrowser.contentWindow;
-      } else {
+      }
+
+      if (!msgContentWindow) {
         return null;
       }
